<?php
// VRM Dashboard — a self-contained Victron VRM dashboard for any PHP web host.
// Generated by VRM Dashboard Builder. Everything lives in this one folder:
//   index.php   this file: the page, the API (?r=…), access control
//   config.php  your settings + VRM token (PHP, so the web server never shows it as text)
//   cache/      short-lived copies of VRM data, stored as PHP files that print nothing
//   page.html, app.js, map.js, style.css   the front end
// Routes: ./ (page) and ./?r=state | history&hours=N | tracks | tracks/export&fmt=gpx|kml&ids=… | refresh

ini_set('display_errors', '0');
error_reporting(E_ALL);

function fail(int $code, string $msg): void {
    http_response_code($code);
    header('Content-Type: text/plain; charset=utf-8');
    header('Cache-Control: private, no-store');
    header('X-Accel-Expires: 0');
    echo $msg . "\n";
    exit;
}

if (!is_readable(__DIR__ . '/config.php')) {
    fail(500, 'Dashboard not configured: config.php is missing. Generate one with the VRM Dashboard Builder.');
}
$CONFIG = require __DIR__ . '/config.php';
if (!is_array($CONFIG) || empty($CONFIG['token']) || empty($CONFIG['site'])) {
    fail(500, 'config.php is incomplete: it needs a VRM token and site ID.');
}
$PANELS = array_merge(['tiles' => true, 'history' => true, 'location' => true, 'lpg' => true,
                       'climate' => true, 'devices' => true], (array)($CONFIG['panels'] ?? []));
define('TOKEN', (string)$CONFIG['token']);
define('SITE', preg_replace('/\D/', '', (string)$CONFIG['site']));
define('SHOW_LOCATION', !empty($PANELS['location']));
define('CACHE', __DIR__ . '/cache');
define('API', 'https://vrmapi.victronenergy.com/v2');
define('STATE_TTL', 55);
define('HISTORY_TTL', 300);
define('TRACKS_TTL', 600);
define('NAMES_TTL', 600);
define('TRACK_DAYS', 365);

if (!is_dir(CACHE)) @mkdir(CACHE, 0700, true);

// --------------------------------------------------------------------------
// Access control

header('Cache-Control: private, no-store');
// Many hosts put an nginx page cache in front of PHP that ignores Cache-Control;
// X-Accel-Expires is nginx's own "do not store" signal.
header('X-Accel-Expires: 0');
header('X-Robots-Tag: noindex, nofollow');
header('Referrer-Policy: same-origin');

function is_https(): bool {
    return (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
        || strtolower($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https'
        || ($_SERVER['SERVER_PORT'] ?? '') === '443'
        || getenv('VRM_ALLOW_HTTP') === '1'; // local testing only
}

function require_auth(array $auth, string $realm): void {
    $user = $_SERVER['PHP_AUTH_USER'] ?? null;
    $pass = $_SERVER['PHP_AUTH_PW'] ?? null;
    if ($user === null) {
        // nginx/PHP-FPM sometimes only passes the raw header
        $h = $_SERVER['HTTP_AUTHORIZATION'] ?? $_SERVER['REDIRECT_HTTP_AUTHORIZATION'] ?? '';
        if (stripos($h, 'basic ') === 0) {
            $pair = explode(':', (string)base64_decode(substr($h, 6), true), 2);
            $user = $pair[0];
            $pass = $pair[1] ?? '';
        }
    }
    if ($user !== null && $user !== '') {
        if (hash_equals((string)$auth['user'], $user) && password_verify((string)$pass, (string)$auth['hash'])) {
            return;
        }
        sleep(2); // slow down password guessing
    }
    header('WWW-Authenticate: Basic realm="' . str_replace('"', '', $realm) . '", charset="UTF-8"');
    fail(401, 'Password required.');
}

// A password is only safe over HTTPS, so password-protected dashboards refuse plain HTTP.
$AUTH = $CONFIG['auth'] ?? null;
if (is_array($AUTH) && !empty($AUTH['user']) && !empty($AUTH['hash'])) {
    if (!is_https()) {
        header('Location: https://' . ($_SERVER['HTTP_HOST'] ?? '') . ($_SERVER['REQUEST_URI'] ?? '/'), true, 301);
        exit;
    }
    require_auth($AUTH, (string)($CONFIG['title'] ?? 'VRM Dashboard'));
}

// --------------------------------------------------------------------------
// HTTP helpers

function vrm_raw(string $path, array $params = []): string {
    $q = [];
    foreach ($params as $k => $v) {
        foreach ((array)$v as $one) $q[] = rawurlencode($k) . '=' . rawurlencode((string)$one);
    }
    $url = API . $path . ($q ? '?' . implode('&', $q) : '');
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_TIMEOUT => 25,
        CURLOPT_CONNECTTIMEOUT => 10,
        CURLOPT_HTTPHEADER => ['X-Authorization: Token ' . TOKEN, 'Accept: application/json'],
        CURLOPT_USERAGENT => 'vrm-dashboard/1.0',
    ]);
    $body = curl_exec($ch);
    $code = (int)curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    $err = curl_error($ch);
    if ($body === false) throw new RuntimeException('VRM unreachable: ' . $err);
    if ($code >= 400) {
        $msg = 'VRM HTTP ' . $code;
        if ($code === 401 || $code === 403) $msg .= ' — token rejected or no access to site ' . SITE;
        if ($code === 429) $msg .= ' — rate limited';
        throw new RuntimeException($msg);
    }
    return $body;
}

function vrm_get(string $path, array $params = []): array {
    $data = json_decode(vrm_raw($path, $params), true);
    if (!is_array($data)) throw new RuntimeException('VRM returned invalid JSON');
    return $data;
}

/** File cache with a lock so concurrent tabs don't stampede VRM. Serves stale data on failure. */
function cached(string $key, int $ttl, callable $fn, bool $force = false) {
    // Stored as .php with an exit guard so a direct web request returns nothing.
    $file = CACHE . '/' . preg_replace('/[^a-z0-9_-]/i', '_', $key) . '.php';
    $read = function () use ($file) {
        if (!is_file($file)) return null;
        $raw = (string)file_get_contents($file);
        $d = json_decode(substr($raw, strpos($raw, "\n") + 1), true);
        return is_array($d) ? $d : null;
    };
    $c = $read();
    if (!$force && $c && time() - $c['t'] < $ttl) return $c['v'];
    $lock = fopen($file . '.lock', 'c');  // empty lock file, nothing to leak
    flock($lock, LOCK_EX);
    try {
        $c = $read();
        if (!$force && $c && time() - $c['t'] < $ttl) return $c['v'];
        try {
            $v = $fn();
        } catch (Throwable $e) {
            if ($c) {
                $v = $c['v'];
                if (is_array($v)) $v['error'] = $e->getMessage();
                return $v;
            }
            throw $e;
        }
        $tmp = $file . '.' . getmypid() . '.tmp';
        file_put_contents($tmp, "<?php exit; ?>\n" . json_encode(['t' => time(), 'v' => $v]));
        rename($tmp, $file);
        return $v;
    } finally {
        flock($lock, LOCK_UN);
        fclose($lock);
    }
}

function send_json($obj): void {
    header('Content-Type: application/json');
    header('Cache-Control: private, no-store');
    echo json_encode($obj, JSON_UNESCAPED_SLASHES | JSON_PARTIAL_OUTPUT_ON_ERROR);
}

// --------------------------------------------------------------------------
// Picking headline metrics out of the diagnostics dump (mirrors server.py)

function num($v): ?float {
    return is_numeric($v) ? (float)$v : null;
}

function find_rec(array $records, array $devKws, array $descKws, array $exclude = []): ?array {
    $hits = [];
    foreach ($records as $r) {
        $d = strtolower((string)($r['Device'] ?? ''));
        foreach ($devKws as $k) {
            if (strpos($d, $k) !== false) { $hits[] = $r; break; }
        }
    }
    foreach ([true, false] as $exact) {
        foreach ($descKws as $kw) {
            foreach ($hits as $r) {
                $d = strtolower((string)($r['description'] ?? ''));
                foreach ($exclude as $x) {
                    if (strpos($d, $x) !== false) continue 2;
                }
                if ($exact ? $d === $kw : strpos($d, $kw) !== false) return $r;
            }
        }
    }
    return null;
}

function by_code(array $records, string $code): ?array {
    foreach ($records as $r) if (($r['code'] ?? null) === $code) return $r;
    return null;
}

function pick_metrics(array $records): array {
    $bat = ['battery monitor', 'battery'];
    $sys = ['system overview'];
    $solar = ['solar charger'];
    $vebus = ['ve.bus'];
    $dcdc = ['alternator', 'dc-dc', 'dc/dc', 'orion']; // Orion XS reports as "Alternator"
    $m = [
        'soc' => find_rec($records, $bat, ['state of charge', 'soc'])
            ?? find_rec($records, $sys, ['battery soc', 'battery state of charge']) ?? by_code($records, 'bs'),
        'batt_v' => find_rec($records, $bat, ['voltage', 'battery voltage'], ['starter', 'mid', 'min', 'max', 'cell'])
            ?? find_rec($records, $sys, ['battery voltage']),
        'batt_a' => find_rec($records, $bat, ['current', 'battery current'], ['charge current limit', 'max'])
            ?? find_rec($records, $sys, ['battery current']),
        'batt_w' => find_rec($records, $bat, ['battery power', 'power']) ?? find_rec($records, $sys, ['battery power']),
        'batt_temp' => find_rec($records, $bat, ['battery temperature', 'temperature'], ['alarm']),
        'ttg' => find_rec($records, $bat, ['time to go']) ?? find_rec($records, $sys, ['battery time to go']),
        'consumed_ah' => find_rec($records, $bat, ['consumed amphours', 'consumed ah']),
        'batt_state' => find_rec($records, $sys, ['battery state']),
        'solar_w' => find_rec($records, $solar, ['pv power', 'pv - dc-coupled']) ?? find_rec($records, $sys, ['pv - dc-coupled', 'pv power']),
        'pv_v' => find_rec($records, $solar, ['pv voltage']),
        'solar_today' => find_rec($records, $solar, ['yield today']),
        'solar_state' => find_rec($records, $solar, ['charge state', 'state']),
        'solar_max_w_today' => find_rec($records, $solar, ['maximum charge power today', 'max charge power today']),
        'ac_load_w' => find_rec($records, $sys, ['ac consumption l1', 'ac consumption']),
        'dc_load_w' => find_rec($records, $sys, ['dc system', 'dc consumption']),
        'shore' => find_rec($records, $sys, ['ac input 1 connected']),
        'vebus_state' => find_rec($records, $vebus, ['ve.bus state', 'state']),
        'vebus_switch' => find_rec($records, $vebus, ['switch position']),
        'ac_in_w' => find_rec($records, $vebus, ['input power 1', 'input power phase 1', 'input power l1']),
        'ac_out_w' => find_rec($records, $vebus, ['output power 1', 'output power phase 1', 'output power l1']),
        'ac_in_v' => find_rec($records, $vebus, ['input voltage phase 1', 'input voltage l1', 'input voltage 1']),
        'dcdc_state' => find_rec($records, $dcdc, ['state', 'charge state', 'device state']),
        'dcdc_out_a' => find_rec($records, $dcdc, ['output current', 'current']),
        'dcdc_in_v' => find_rec($records, $dcdc, ['input voltage']),
        'dcdc_off_reason' => find_rec($records, $dcdc, ['device off reason']),
        'dcdc_ah' => find_rec($records, $dcdc, ['charged ah']),
        'gx_relay' => find_rec($records, ['gateway'], ['relay 1 state']),
    ];
    foreach (['gps_lat' => 'lt', 'gps_lon' => 'lg', 'gps_alt' => 'la', 'gps_speed' => 'ls',
              'gps_course' => 'lc', 'gps_speed_unit' => 'gsu'] as $k => $code) {
        $m[$k] = by_code($records, $code);
    }
    return array_filter($m);
}

const HISTORY_KEYS = ['soc', 'batt_v', 'batt_a', 'batt_w', 'solar_w', 'ac_load_w', 'dc_load_w', 'ac_out_w', 'batt_temp'];

function group_devices(array $records): array {
    $groups = [];
    foreach ($records as $r) {
        $key = ($r['Device'] ?? 'Unknown') . "\0" . json_encode($r['instance'] ?? null);
        if (!isset($groups[$key])) $groups[$key] = ['device' => $r['Device'] ?? 'Unknown', 'instance' => $r['instance'] ?? null, 'records' => []];
        $groups[$key]['records'][] = $r;
    }
    $out = array_values($groups);
    foreach ($out as &$g) {
        usort($g['records'], fn($a, $b) => strcmp((string)($a['description'] ?? ''), (string)($b['description'] ?? '')));
    }
    unset($g);
    usort($out, function ($a, $b) {
        $c = strcmp($a['device'], $b['device']);
        return $c ?: (($a['instance'] ?? -1) <=> ($b['instance'] ?? -1));
    });
    return $out;
}

function active_alarms(array $records): array {
    $ok = ['', 'ok', 'no alarm', 'no error', 'none', '0', '-', 'no warning', 'disabled', 'enabled'];
    $out = [];
    foreach ($records as $r) {
        $d = strtolower((string)($r['description'] ?? ''));
        if (strpos($d, 'alarm') === false && strpos($d, 'error') === false && strpos($d, 'warning') === false) continue;
        if (strpos($d, 'last error') !== false || strpos($d, 'error count') !== false || strpos($d, 'flags') !== false) continue;
        $fv = trim((string)($r['formattedValue'] ?? ''));
        $low = strtolower($fv);
        if (in_array($low, $ok, true) || strpos($low, 'no error') !== false || strpos($low, 'ok') === 0) continue;
        if (num($r['rawValue'] ?? null) === 0.0) continue;
        $out[] = [
            'device' => $r['Device'] ?? null, 'instance' => $r['instance'] ?? null,
            'description' => $r['description'] ?? null, 'value' => $fv, 'timestamp' => $r['timestamp'] ?? null,
            'level' => (strpos($low, 'alarm') !== false || num($r['rawValue'] ?? null) === 2.0) ? 'critical' : 'warning',
        ];
    }
    return $out;
}

function names(): array {
    try {
        return cached('names', NAMES_TTL, function () {
            $so = vrm_get('/installations/' . SITE . '/system-overview');
            $names = [];
            foreach (($so['records']['devices'] ?? []) as $d) {
                $inst = $d['instance'] ?? null;
                $names[($d['name'] ?? '') . '|' . ($inst === null ? 'None' : $inst)] = [
                    'label' => $d['customName'] ?? $d['productName'] ?? $d['name'] ?? null,
                    'product' => $d['productName'] ?? null, 'firmware' => $d['firmwareVersion'] ?? null,
                    'lastConnection' => $d['lastConnection'] ?? null, 'class' => $d['class'] ?? null,
                    'name' => $d['name'] ?? null,
                ];
            }
            return $names;
        });
    } catch (Throwable $e) {
        return []; // cosmetic only
    }
}

const GPS_CODES = ['lt', 'lg', 'la', 'ls', 'lc', 'gsu'];

function build_state(): array {
    $resp = vrm_get('/installations/' . SITE . '/diagnostics', ['count' => 1000]);
    $records = $resp['records'] ?? [];
    if (!SHOW_LOCATION) {
        // Map turned off: drop position data server-side so it can't be read from the API either.
        $records = array_values(array_filter($records, function ($r) {
            return !in_array($r['code'] ?? '', GPS_CODES, true)
                && strpos((string)($r['dbusPath'] ?? ''), '/Position') !== 0;
        }));
    }
    $metrics = pick_metrics($records);
    $values = [];
    foreach (HISTORY_KEYS as $k) if (isset($metrics[$k])) $values[$k] = num($metrics[$k]['rawValue'] ?? null);
    if (($values['batt_w'] ?? null) === null && isset($values['batt_v'], $values['batt_a'])) {
        $values['batt_w'] = round($values['batt_v'] * $values['batt_a'], 1);
    }
    $ts = 0;
    foreach ($records as $r) $ts = max($ts, (int)($r['timestamp'] ?? 0));
    return [
        'ok' => true, 'error' => null, 'fetched_at' => time(), 'site' => SITE, 'poll_seconds' => STATE_TTL + 5,
        'data_ts' => $ts ?: time(), 'metrics' => (object)$metrics, 'values' => (object)$values,
        'devices' => group_devices($records), 'alarms' => active_alarms($records),
        'record_count' => count($records),
    ];
}

function state(bool $force = false): array {
    try {
        $s = cached('state', STATE_TTL, 'build_state', $force);
        $s['ok'] = empty($s['error']);
    } catch (Throwable $e) {
        $s = ['ok' => false, 'error' => $e->getMessage(), 'site' => SITE, 'poll_seconds' => STATE_TTL + 5];
    }
    $s['names'] = (object)names();
    return $s;
}

// --------------------------------------------------------------------------
// History straight from VRM stats (no local poller on shared hosting)

function history(float $hours): array {
    $hours = max(1, min(24 * 31, $hours));
    $bucket = $hours <= 6 ? 6 : ($hours <= 24 ? 24 : ($hours <= 72 ? 72 : ($hours <= 168 ? 168 : 744)));
    return cached('history_' . $bucket, HISTORY_TTL, function () use ($bucket) {
        $st = state();
        $metrics = (array)($st['metrics'] ?? []);
        $want = ['soc', 'batt_w', 'solar_w', 'ac_load_w', 'dc_load_w'];
        if (!isset($metrics['batt_w'])) array_push($want, 'batt_v', 'batt_a');
        $byInst = [];
        foreach ($want as $k) {
            $rec = $metrics[$k] ?? null;
            if (!$rec || empty($rec['code'])) continue;
            $byInst[json_encode($rec['instance'] ?? null)][$k] = $rec['code'];
        }
        $end = time();
        $start = $end - $bucket * 3600;
        $interval = $bucket <= 72 ? '15mins' : 'hours';
        $series = [];
        foreach ($byInst as $instJson => $keys) {
            $params = ['type' => 'custom', 'attributeCodes[]' => array_values(array_unique($keys)),
                       'interval' => $interval, 'start' => $start, 'end' => $end];
            $inst = json_decode($instJson, true);
            if ($inst !== null) $params['instance'] = $inst;
            $resp = vrm_get('/installations/' . SITE . '/stats', $params);
            foreach ($keys as $k => $code) {
                $pts = [];
                foreach (($resp['records'][$code] ?? []) as $p) {
                    if (is_array($p) && count($p) > 1 && $p[1] !== null) $pts[] = [(int)($p[0] / 1000), (float)$p[1]];
                }
                $series[$k] = $pts;
            }
        }
        if (!isset($series['batt_w']) && isset($series['batt_v'], $series['batt_a'])) {
            $a = [];
            foreach ($series['batt_a'] as [$t, $v]) $a[$t] = $v;
            $series['batt_w'] = [];
            foreach ($series['batt_v'] as [$t, $v]) if (isset($a[$t])) $series['batt_w'][] = [$t, round($v * $a[$t], 1)];
        }
        return $series;
    });
}

function history_with_live(float $hours): array {
    $series = history($hours);
    unset($series['error']);
    // Stats are 15-min averages; tack the live reading on so the line ends "now".
    $st = state();
    $ts = (int)($st['data_ts'] ?? 0);
    foreach ((array)($st['values'] ?? []) as $k => $v) {
        if ($v === null || !isset($series[$k])) continue;
        $last = end($series[$k]);
        if (!$last || $ts > $last[0]) $series[$k][] = [$ts, $v];
    }
    return $series;
}

// --------------------------------------------------------------------------
// GPS tracks: VRM exports trips as KML, one Placemark per trip named
// "YYYY-mm-dd HH:MM:SS - YYYY-mm-dd HH:MM:SS" (UTC), coordinates "lon,lat ...".

function km(array $pts): float {
    $d = 0.0;
    for ($i = 1, $n = count($pts); $i < $n; $i++) {
        [$la1, $lo1] = $pts[$i - 1];
        [$la2, $lo2] = $pts[$i];
        $p1 = deg2rad($la1); $p2 = deg2rad($la2);
        $a = sin(($p2 - $p1) / 2) ** 2 + cos($p1) * cos($p2) * sin(deg2rad($lo2 - $lo1) / 2) ** 2;
        $d += 2 * 6371.0 * asin(sqrt($a));
    }
    return round($d, 2);
}

function utc_ts(string $s): ?int {
    $dt = DateTime::createFromFormat('Y-m-d H:i:s', trim($s), new DateTimeZone('UTC'));
    return $dt ? $dt->getTimestamp() : null;
}

function parse_kml(string $data): array {
    $ns = 'http://www.opengis.net/kml/2.2';
    $doc = new DOMDocument();
    if (!@$doc->loadXML($data, LIBXML_NONET)) throw new RuntimeException('VRM track export was not valid KML');
    $tracks = [];
    foreach ($doc->getElementsByTagNameNS($ns, 'Placemark') as $pm) {
        $nameEl = $pm->getElementsByTagNameNS($ns, 'name')->item(0);
        $name = $nameEl ? trim($nameEl->textContent) : '';
        $pts = [];
        foreach ($pm->getElementsByTagNameNS($ns, 'coordinates') as $c) {
            foreach (preg_split('/\s+/', trim($c->textContent)) as $tok) {
                $parts = explode(',', $tok);
                if (count($parts) >= 2 && is_numeric($parts[0]) && is_numeric($parts[1])) {
                    $pts[] = [round((float)$parts[1], 6), round((float)$parts[0], 6)];
                }
            }
        }
        if (!$pts) continue;
        $start = $end = null;
        if (strpos($name, ' - ') !== false) {
            [$a, $b] = explode(' - ', $name, 2);
            $start = utc_ts($a);
            $end = utc_ts($b);
        }
        $tracks[] = ['id' => (string)($start ?? count($tracks)), 'name' => $name, 'start' => $start,
                     'end' => $end, 'km' => km($pts), 'points' => $pts];
    }
    usort($tracks, fn($a, $b) => ($a['start'] ?? 0) <=> ($b['start'] ?? 0));
    return $tracks;
}

function tracks(): array {
    try {
        return cached('tracks', TRACKS_TTL, function () {
            $end = time();
            $kml = vrm_raw('/installations/' . SITE . '/gps-download', ['start' => $end - TRACK_DAYS * 86400, 'end' => $end]);
            return ['tracks' => parse_kml($kml), 'fetched_at' => $end, 'error' => null];
        });
    } catch (Throwable $e) {
        return ['tracks' => [], 'fetched_at' => null, 'error' => $e->getMessage()];
    }
}

function dash_title(): string {
    global $CONFIG;
    return (string)($CONFIG['title'] ?? 'VRM Dashboard');
}

function xesc(string $s): string {
    return htmlspecialchars($s, ENT_XML1 | ENT_QUOTES, 'UTF-8');
}

function export_tracks(array $tracks, string $fmt): void {
    $out = [];
    if ($fmt === 'gpx') {
        $out[] = '<?xml version="1.0" encoding="UTF-8"?>';
        $out[] = '<gpx version="1.1" creator="vrm-dashboard" xmlns="http://www.topografix.com/GPX/1/1">';
        foreach ($tracks as $t) {
            $out[] = '  <trk><name>' . xesc($t['name']) . '</name><trkseg>';
            foreach ($t['points'] as [$la, $lo]) $out[] = '    <trkpt lat="' . $la . '" lon="' . $lo . '"/>';
            $out[] = '  </trkseg></trk>';
        }
        $out[] = '</gpx>';
        $ctype = 'application/gpx+xml';
    } else {
        $out[] = '<?xml version="1.0" encoding="UTF-8"?>';
        $out[] = '<kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>' . xesc(dash_title()) . '</name>';
        foreach ($tracks as $t) {
            $coords = implode(' ', array_map(fn($p) => $p[1] . ',' . $p[0], $t['points']));
            $out[] = '<Placemark><name>' . xesc($t['name']) . '</name><LineString><tessellate>1</tessellate><coordinates>'
                . $coords . '</coordinates></LineString></Placemark>';
        }
        $out[] = '</Document></kml>';
        $ctype = 'application/vnd.google-earth.kml+xml';
    }
    $body = implode("\n", $out);
    header('Content-Type: ' . $ctype);
    $slug = trim(preg_replace('/[^a-z0-9]+/', '-', strtolower(dash_title())), '-') ?: 'vrm';
    header('Content-Disposition: attachment; filename="' . $slug . '-tracks-' . date('Ymd') . '.' . $fmt . '"');
    header('Content-Length: ' . strlen($body));
    header('Cache-Control: private, no-store');
    echo $body;
}

// --------------------------------------------------------------------------
// Router

$route = trim((string)($_GET['r'] ?? ''), '/');
try {
    switch ($route) {
        case '':
            $tpl = __DIR__ . '/page.html';
            if (!is_readable($tpl)) throw new RuntimeException('page.html is missing from the dashboard folder.');
            $html = (string)file_get_contents($tpl);
            // Remove the panels this dashboard has turned off (marked <!--panel:x--> … <!--/panel:x-->).
            foreach ($PANELS as $name => $on) {
                if (!$on) $html = preg_replace('#<!--panel:' . $name . '-->.*?<!--/panel:' . $name . '-->#s', '', $html);
            }
            $html = preg_replace('#<div class="two-col">\s*</div>#', '', $html); // both side panels off
            $title = htmlspecialchars((string)($CONFIG['title'] ?? 'VRM Dashboard'), ENT_QUOTES, 'UTF-8');
            $html = str_replace('{{TITLE}}', $title, $html);
            $theme = (string)($CONFIG['theme'] ?? 'auto');
            if ($theme === 'light' || $theme === 'dark') {
                // Set in the HTML so the page never flashes the wrong theme; a visitor's ◐ choice still wins.
                $html = str_replace('<html lang="en">', '<html lang="en" data-theme="' . $theme . '">', $html);
            }
            $client = ['title' => (string)($CONFIG['title'] ?? 'VRM Dashboard'),
                       'units' => ($CONFIG['units'] ?? 'us') === 'metric' ? 'metric' : 'us',
                       'theme' => $theme, 'panels' => $PANELS];
            // The host caches .js/.css for months; version the URLs so updates show up.
            foreach (['style.css', 'app.js', 'map.js'] as $asset) {
                $v = @filemtime(__DIR__ . '/' . $asset) ?: time();
                $html = str_replace('"' . $asset . '"', '"' . $asset . '?v=' . $v . '"', $html);
            }
            $html = str_replace('<script src="app.js?',
                '<script>window.DASH_API = "./?r="; window.DASH_CONFIG = '
                . json_encode($client, JSON_HEX_TAG | JSON_HEX_AMP | JSON_UNESCAPED_SLASHES) . ';</script>'
                . "\n" . '<script src="app.js?', $html);
            header('Content-Type: text/html; charset=utf-8');
            echo $html;
            break;
        case 'state':
            send_json(state());
            break;
        case 'history':
            send_json((object)history_with_live((float)($_GET['hours'] ?? 24)));
            break;
        case 'tracks':
        case 'tracks/export':
            if (!SHOW_LOCATION) {
                http_response_code(404);
                send_json(['error' => 'location is turned off for this dashboard']);
                break;
            }
            if ($route === 'tracks') {
                send_json(tracks());
                break;
            }
            $fmt = ($_GET['fmt'] ?? 'gpx') === 'kml' ? 'kml' : 'gpx';
            $ids = array_filter(explode(',', (string)($_GET['ids'] ?? '')), 'strlen');
            $all = tracks()['tracks'];
            $sel = $ids ? array_values(array_filter($all, fn($t) => in_array($t['id'], $ids, true))) : $all;
            export_tracks($sel, $fmt);
            break;
        case 'refresh':
            // Bypass the state cache, but never hit VRM more than every 15 s.
            $f = CACHE . '/state.php';
            $age = is_file($f) ? time() - filemtime($f) : 999;
            state($age >= 15);
            send_json(['ok' => true]);
            break;
        default:
            http_response_code(404);
            send_json(['error' => 'unknown route']);
    }
} catch (Throwable $e) {
    if ($route === '') {
        http_response_code(500);
        header('Content-Type: text/plain; charset=utf-8');
        echo "Dashboard error: " . $e->getMessage() . "\n";
    } else {
        http_response_code(502);
        send_json(['ok' => false, 'error' => $e->getMessage()]);
    }
}
